package cache

import (
	"context"
	"time"
)

// Cache — универсальный интерфейс кэша данных с generics (Cache Contract pattern).
//
// Определяет сквозной высокоуровневый контракт для работы с подсистемой кэширования фреймворка.
// За счет инкапсуляции обобщенных типов (Generics) полностью исключает ручной кастинг интерфейсов,
// гарантируя строгую типизацию, безопасность работы с памятью и чистоту прикладного доменного слоя.
type Cache[K comparable, V any] interface {
	// Get возвращает десериализованную копию сохраненного объекта из памяти или L2-контура.
	// Булев флаг (ok) сигнализирует о фактическом наличии или промахе кэша (Cache Miss).
	Get(key K) (value V, ok bool, err error)

	// Set сериализует объект и сохраняет его в кэш с жестким ограничением времени жизни (TTL).
	Set(key K, value V, ttl time.Duration) error

	// Delete принудительно удаляет ключ из кэш-хранилища и очищает внутренние индексы вытеснения.
	Delete(key K)

	// Size возвращает текущее суммарное количество элементов, удерживаемых в оперативной памяти кэша.
	Size() int

	// Clear выполняет полный транзакционный сброс и очистку памяти всех сегментов кэша.
	Clear()

	// CacheJanitor запускает такт фоновой очистки просроченных по TTL записей (Garbage Collection).
	// Вызывается периодически внешним планировщиком (шедулером) с передачей контекста отмены.
	CacheJanitor(ctx context.Context, eventTime time.Time) error
}
